        pmb->pcoord->Face1Area(k,j,is,ie+1,area);
        pmb->pcoord->Edge3Length(k,j  ,is,ie+1,len);
        pmb->pcoord->Edge3Length(k,j+1,is,ie+1,len_p1);
#pragma omp simd
